#!/usr/bin/env python3
"""Convert a .elml model into a C header containing a flash-friendly blob."""
import sys
from pathlib import Path


def main() -> int:
    if len(sys.argv) != 3:
        print("usage: embed_model.py MODEL.elml OUTPUT.h", file=sys.stderr)
        return 2

    source = Path(sys.argv[1])
    target = Path(sys.argv[2])
    data = source.read_bytes()
    if not data:
        print("embed_model.py: empty model", file=sys.stderr)
        return 1

    lines = [
        "/* Generated by embed_model.py. Do not edit. */",
        "#ifndef ELML_EXAMPLE_MODEL_BLOB_H",
        "#define ELML_EXAMPLE_MODEL_BLOB_H",
        "",
        "#include <stddef.h>",
        "#include <stdint.h>",
        "",
        "#if defined(__GNUC__) || defined(__clang__)",
        "#  define ELML_EXAMPLE_ALIGN64 __attribute__((aligned(64)))",
        "#elif defined(_MSC_VER)",
        "#  define ELML_EXAMPLE_ALIGN64 __declspec(align(64))",
        "#else",
        "#  define ELML_EXAMPLE_ALIGN64",
        "#endif",
        "",
        "static const uint8_t elml_example_model[] ELML_EXAMPLE_ALIGN64 = {",
    ]
    for offset in range(0, len(data), 12):
        chunk = data[offset:offset + 12]
        values = ", ".join(f"0x{byte:02x}" for byte in chunk)
        lines.append(f"  {values},")
    lines.extend([
        "};",
        f"static const size_t elml_example_model_len = {len(data)}u;",
        "",
        "#endif /* ELML_EXAMPLE_MODEL_BLOB_H */",
        "",
    ])
    target.write_text("\n".join(lines))
    print(f"embedded {len(data)} bytes into {target}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
